<?php

declare(strict_types=1);

namespace App\Tests\Controller;

use App\Entity\UserAvailabilityType;
use App\Repository\UserRepository;
use App\Service\UserAvailabilityService;
use App\Tests\LineFillTestHelpers;
use Doctrine\DBAL\Connection;
use Symfony\Bundle\FrameworkBundle\KernelBrowser;
use Symfony\Bundle\FrameworkBundle\Test\WebTestCase;

/**
 * docs/decisions.md D222, second round:
 *
 * - "Générer le planning" never replaces the calendar of a line already
 *   generated by default — only with the explicit confirmation
 *   `replaceExistingAssignments` (and the technical per-period API alike);
 * - a member who joined after a line's generation is taken into account by
 *   its completion — appended to the snapshot, flagged late, with their
 *   unavailabilities respected — the rows frozen at generation time intact.
 *
 * Fixture (pilotScenario): Seniors = admin, alice, bob; planning 2027-01-01 → 2027-05-01.
 */
final class PlanningRegenerationAndLateMemberTest extends WebTestCase
{
    use LineFillTestHelpers;

    private KernelBrowser $client;

    /** @var array<string, mixed> */
    private array $s;

    protected function setUp(): void
    {
        $this->client = static::createClient();
        $this->s = $this->pilotScenario($this->client);
    }

    private function db(): Connection
    {
        return static::getContainer()->get(Connection::class);
    }

    private function unavailable(string $email, string $fromUtc, string $toUtc): void
    {
        static::getContainer()->get(UserAvailabilityService::class)->create(
            static::getContainer()->get(UserRepository::class)->findOneByEmail($email),
            UserAvailabilityType::UNAVAILABLE,
            new \DateTimeImmutable($fromUtc.' UTC'),
            new \DateTimeImmutable($toUtc.' UTC'),
        );
    }

    private function jobCount(): int
    {
        return (int) $this->db()->fetchOne('SELECT COUNT(*) FROM planning_jobs');
    }

    /**
     * Without confirmation, "Générer le planning" on a generated line is
     * refused before any job — nothing written; the preflight says why. With
     * the explicit confirmation, it runs, and the calendar is replaced.
     */
    public function testRegeneratingAGeneratedLineRequiresAnExplicitConfirmation(): void
    {
        $this->prepareLine($this->s['planningId'], self::days('2027-01-04', 3));
        self::assertSame('SUCCEEDED', $this->generateNow($this->client, $this->s['planningId'], $this->s['creator'])['status']);
        $before = $this->protectedRows();
        $visible = $this->visibleLine($this->client, $this->s, 0);
        $jobs = $this->jobCount();

        $preflight = $this->api($this->client, 'GET', "/api/plannings/{$this->s['planningId']}/generation-preflight", token: $this->s['creator']);
        self::assertContains('REGENERATION_NOT_CONFIRMED', array_column($preflight['blockers'], 'code'));
        $refusal = $this->api($this->client, 'POST', "/api/plannings/{$this->s['planningId']}/generations", [], $this->s['creator']);
        self::assertResponseStatusCodeSame(409);
        self::assertSame('not_launchable', $refusal['error']);
        self::assertContains('REGENERATION_NOT_CONFIRMED', array_column($refusal['blockers'], 'code'));
        // Not "true" enough: only the boolean true confirms.
        $this->api($this->client, 'POST', "/api/plannings/{$this->s['planningId']}/generations", ['replaceExistingAssignments' => 'yes'], $this->s['creator']);
        self::assertResponseStatusCodeSame(409);

        self::assertSame($jobs, $this->jobCount(), 'No job queued.');
        self::assertSame(0, $this->queuedPlanningJobMessageCount());
        $this->assertNoExistingRowChanged($before);
        self::assertSame($visible, $this->visibleLine($this->client, $this->s, 0));

        $confirmed = $this->api($this->client, 'GET', "/api/plannings/{$this->s['planningId']}/generation-preflight?replaceExisting=1", token: $this->s['creator']);
        self::assertNotContains('REGENERATION_NOT_CONFIRMED', array_column($confirmed['blockers'], 'code'));
        $job = $this->generateNow($this->client, $this->s['planningId'], $this->s['creator'], ['replaceExistingAssignments' => true]);
        self::assertSame('SUCCEEDED', $job['status']);
        self::assertTrue((bool) $this->db()->fetchOne('SELECT replace_existing FROM planning_jobs ORDER BY id DESC LIMIT 1'), 'The confirmation is recorded on the job.');
        self::assertNotSame(array_column($visible, 0), array_column($this->visibleLine($this->client, $this->s, 0), 0), 'Confirmed: a new generation, new assignments.');
    }

    /** The technical per-period API (no screen uses it) is held to the same rule. */
    public function testThePerPeriodApiAlsoRefusesAnUnconfirmedRegeneration(): void
    {
        $this->prepareLine($this->s['planningId'], self::days('2027-01-04', 2));
        $this->generateNow($this->client, $this->s['planningId'], $this->s['creator']);
        $periodId = $this->api($this->client, 'GET', "/api/plannings/{$this->s['planningId']}", token: $this->s['creator'])['lines'][0]['planningPeriodStableId'];
        $generations = (int) $this->db()->fetchOne('SELECT COUNT(*) FROM planning_generations');

        $refusal = $this->api($this->client, 'POST', "/api/planning-periods/{$periodId}/generations", [], $this->s['admin']);

        self::assertResponseStatusCodeSame(409);
        self::assertSame('regeneration_not_confirmed', $refusal['error']);
        self::assertSame($generations, (int) $this->db()->fetchOne('SELECT COUNT(*) FROM planning_generations'));
        $this->api($this->client, 'POST', "/api/planning-periods/{$periodId}/generations", ['replaceExistingAssignments' => true], $this->s['admin']);
        self::assertResponseStatusCodeSame(201);
    }

    /**
     * Carol joins after the Seniors were generated. The hole of 5 January,
     * which nobody of the generation can take (all unavailable), goes to her
     * — appended to the snapshot, flagged late; every row frozen with the
     * snapshot, every existing assignment untouched.
     */
    public function testAMemberWhoJoinedAfterTheGenerationReceivesAHole(): void
    {
        $this->prepareLine($this->s['planningId'], self::days('2027-01-04', 3));
        $this->generateNow($this->client, $this->s['planningId'], $this->s['creator']);
        $this->unassignDuty($this->client, $this->s, $this->dutyOn($this->s['planningId'], '2027-01-05'));
        self::assertResponseIsSuccessful();
        foreach (['admin@example.com', 'alice@example.com', 'bob@example.com'] as $email) {
            $this->unavailable($email, '2027-01-05 00:00', '2027-01-06 00:00');
        }
        $this->userToken($this->client, 'carol@example.com');
        $this->addMemberAs($this->client, $this->s['creator'], $this->s['planningId'], $this->s['teamId'], 'carol@example.com', 'MEMBER');
        $before = $this->protectedRows();
        $snapshotMembers = $this->db()->fetchAllAssociative('SELECT id, md5(t::text) AS h FROM planning_snapshot_members t ORDER BY id');

        $preview = $this->fillPreview($this->client, $this->s)['lines'][0];
        self::assertSame(['COMPLETE', 1, 1], [$preview['action'], $preview['uncoveredRequiredDutyCount'], $preview['lateMemberCount']]);

        $job = $this->fillNow($this->client, $this->s, [$preview['lineStableId']]);

        $line = $this->fillLines($job)['Seniors'];
        self::assertSame(['done', 2, 0, 1, 0], [$line['status'], $line['keptCount'], $line['modifiedCount'], $line['addedCount'], $line['remainingUncoveredCount']]);
        self::assertSame('carol@example.com', $this->currentCalendar($this->s['planningId'])['0|2027-01-05|ONCALL']);
        $this->assertNoExistingRowChanged($before);
        // The snapshot: every member frozen at generation time identical; one more, flagged late — Carol.
        foreach ($snapshotMembers as $row) {
            self::assertSame($row['h'], $this->db()->fetchOne('SELECT md5(t::text) FROM planning_snapshot_members t WHERE id = ?', [$row['id']]));
        }
        $late = $this->db()->fetchAllAssociative(<<<'SQL'
            SELECT u.email FROM planning_snapshot_members sm JOIN users u ON u.stable_id = sm.source_user_stable_id
            WHERE sm.captured_late_at IS NOT NULL
            SQL);
        self::assertSame([['email' => 'carol@example.com']], $late);
        self::assertSame(0, (int) $this->db()->fetchOne('SELECT COUNT(*) FROM planning_snapshot_members WHERE captured_late_at IS NULL AND id > ?', [max(array_column($snapshotMembers, 'id'))]));
    }

    /**
     * A late member's unavailabilities are respected like anybody's: Carol is
     * unavailable too — the hole stays uncovered, nothing else moves.
     */
    public function testALateMembersUnavailabilityIsRespected(): void
    {
        $this->prepareLine($this->s['planningId'], self::days('2027-01-04', 3));
        $this->generateNow($this->client, $this->s['planningId'], $this->s['creator']);
        $this->unassignDuty($this->client, $this->s, $this->dutyOn($this->s['planningId'], '2027-01-05'));
        $this->userToken($this->client, 'carol@example.com');
        $this->addMemberAs($this->client, $this->s['creator'], $this->s['planningId'], $this->s['teamId'], 'carol@example.com', 'MEMBER');
        foreach (['admin@example.com', 'alice@example.com', 'bob@example.com', 'carol@example.com'] as $email) {
            $this->unavailable($email, '2027-01-05 00:00', '2027-01-06 00:00');
        }
        $before = $this->protectedRows();

        $job = $this->fillNow($this->client, $this->s, [$this->lineIds($this->client, $this->s)[0]]);

        $line = $this->fillLines($job)['Seniors'];
        self::assertSame(['done', 0, 1, 0], [$line['status'], $line['addedCount'], $line['remainingUncoveredCount'], $line['modifiedCount']]);
        self::assertNull($this->currentCalendar($this->s['planningId'])['0|2027-01-05|ONCALL']);
        $this->assertNoExistingRowChanged($before);
    }
}
